"""Locale strings for the AI crawler directory (/bots) and the platform directory (/platforms), RES-4194.
Every page-level sentence of a generated crawler page lives here; per-crawler prose lives in data/directory/texts_<loc>.json."""
LOCS = ("en", "fr", "de", "es", "nl")
MONTHS = {
    "en": "January February March April May June July August September October November December".split(),
    "fr": "janvier février mars avril mai juin juillet août septembre octobre novembre décembre".split(),
    "de": "Januar Februar März April Mai Juni Juli August September Oktober November Dezember".split(),
    "es": "enero febrero marzo abril mayo junio julio agosto septiembre octubre noviembre diciembre".split(),
    "nl": "januari februari maart april mei juni juli augustus september oktober november december".split(),
}
def date_txt(loc, iso):
    y, m, d = (int(x) for x in iso.split("-")); mo = MONTHS[loc][m - 1]
    return {"en": "%d %s %d", "fr": "%d %s %d", "de": "%d. %s %d", "es": "%d de %s de %d", "nl": "%d %s %d"}[loc] % (d, mo, y)

